INSERT INTO `animals` (`id`, `prenom`, `race`, `habitat_id`, `diet`, `description`, `characteristics`, `image`, `species`, `lifespan`, `size_weight`, `gestation`, `natural_habitat`, `native_region`, `lifestyle`, `distinctive_features`) VALUES
	(1, 'Simba', 'Lion (Panthera leo)', 1, 'Carnivore', 'The lion is a large feline with a majestic mane.', 'Lions live in groups called prides and are known for their strength and hunting skills.', _binary , 'Panthera leo', '10-14 years in the wild, up to 20 in captivity', 'Males: 150-250 kg, Females: 120-182 kg; Body length: 1.4-2.5 m', '110 days, 1-6 cubs', 'Grasslands, savannas, dense bush', 'Sub-Saharan Africa, small population in India', 'Lions are the only truly social cats, living in prides. They are apex predators and are known for their teamwork in hunting.', 'Males have distinctive manes. Powerful build with strong jaws and retractable claws. Tawny coat provides camouflage in grasslands.');
INSERT INTO `animals` (`id`, `prenom`, `race`, `habitat_id`, `diet`, `description`, `characteristics`, `image`, `species`, `lifespan`, `size_weight`, `gestation`, `natural_habitat`, `native_region`, `lifestyle`, `distinctive_features`) VALUES
	(2, 'Twiga', 'Giraffe (Giraffa camelopardalis)', 1, 'Herbivore', 'The giraffe is the tallest land animal, known for its long neck.', 'Giraffes use their long necks to reach leaves high in trees.', _binary , 'Giraffa camelopardalis', 'Up to 25 years in the wild, 28 in captivity', 'Males: up to 5.5 m tall, 1,900 kg; Females: up to 4.3 m tall, 1,180 kg', '15 months, usually 1 calf', 'Savannas, grasslands, open woodlands', 'Sub-Saharan Africa', 'Giraffes are social animals living in loose herds. They are browsers, feeding on leaves high in trees that other herbivores can\'t reach.', 'Extremely long neck and legs, spotted coat pattern unique to each individual, small ossicones on head.'),
	(3, 'Nia', 'African Elephant (Loxodonta africana)', 1, 'Herbivore', 'The African elephant is the largest land animal.', 'Elephants are social animals known for their intelligence and strong family bonds.', _binary , 'Loxodonta africana', '60-70 years', 'Males: up to 6,000 kg; Females: up to 3,000 kg; Height: 2.4-3.4 m at the shoulder', '22 months, usually 1 calf', 'Savannas, forests, deserts', 'Sub-Saharan Africa', 'Highly social animals living in herds led by a matriarch. Known for their intelligence, memory, and complex social structures.', 'Largest land animal, distinctive long trunk, large ears, tusks in both males and females.');
INSERT INTO `animals` (`id`, `prenom`, `race`, `habitat_id`, `diet`, `description`, `characteristics`, `image`, `species`, `lifespan`, `size_weight`, `gestation`, `natural_habitat`, `native_region`, `lifestyle`, `distinctive_features`) VALUES
	(4, 'Zazu', 'Southern Ground Hornbill (Bucorvus leadbeateri)', 1, 'Omnivore', 'The ground hornbill is a large bird found in the savannah.', 'Ground hornbills are known for their deep calls and impressive size.', _binary , 'Bucorvus leadbeateri', 'Up to 50-60 years', 'Weight: 3.5-6.2 kg; Length: 90-129 cm', '38-41 days incubation, 1-2 eggs', 'Savannas, grasslands with scattered trees', 'Eastern and southern Africa', 'Live in cooperative breeding groups. Spend most of their time on the ground foraging for food.', 'Large black bird with vivid red facial skin and throat pouch. Long eyelashes, sharp beak, and powerful legs.');
INSERT INTO `animals` (`id`, `prenom`, `race`, `habitat_id`, `diet`, `description`, `characteristics`, `image`, `species`, `lifespan`, `size_weight`, `gestation`, `natural_habitat`, `native_region`, `lifestyle`, `distinctive_features`) VALUES
	(5, 'Pumbaa', 'Warthog (Phacochoerus africanus)', 1, 'Omnivore', 'The warthog is a wild member of the pig family.', 'Warthogs are known for their distinctive tusks and wart-like growths on their faces.', _binary , 'Phacochoerus africanus', '12-18 years in the wild', 'Weight: 50-150 kg; Body length: 0.9-1.5 m', '5-6 months, 2-8 piglets', 'Savannas, grasslands, woodlands', 'Sub-Saharan Africa', 'Often seen in small family groups. Known for their habit of kneeling on their front legs while grazing.', 'Distinctive facial warts, large curved tusks, mane running down the spine. Can run up to 48 km/h.'),
	(6, 'Bagheera', 'Jaguar (Panthera onca)', 2, 'Carnivore', 'The jaguar is a large, powerful cat native to the Americas.', 'Jaguars have a strong bite that allows them to pierce the shells of turtles and other prey.', _binary , 'Panthera onca', '12-15 years in the wild, up to 20 in captivity', 'Weight: 56-96 kg; Body length: 1.12-1.85 m', '93-105 days, 1-4 cubs', 'Tropical and subtropical forests, swamps', 'Central and South America', 'Solitary animals, excellent swimmers and climbers. Known for their powerful bite force.', 'Stocky build, rosette-patterned coat, largest cat in the Americas. Powerful jaws can pierce turtle shells.'),
	(7, 'Mowgli', 'Mantled Howler Monkey (Alouatta palliata)', 2, 'Herbivore', 'The howler monkey is known for its loud howls.', 'Howler monkeys have a specialized throat and large hyoid bone that enables their vocalizations.', _binary , 'Alouatta palliata', '15-20 years', 'Weight: 4-9 kg; Body length: 55-92 cm', '6 months, usually 1 infant', 'Tropical and subtropical forests', 'Central and South America', 'Live in troops of 10-20 individuals. Known for their loud howls that can be heard up to 5 km away.', 'Black body with golden-brown saddle, prehensile tail, enlarged hyoid bone for vocalization.'),
	(8, 'Kaa', 'Green Anaconda (Eunectes murinus)', 2, 'Carnivore', 'The green anaconda is one of the largest snakes in the world.', 'Anacondas are excellent swimmers and often ambush their prey from water.', _binary , 'Eunectes murinus', '10 years in the wild, up to 30 in captivity', 'Weight: up to 227 kg; Length: average 5 m, can reach 9 m', 'Ovoviviparous, 6-7 months gestation, 20-40 live young', 'Tropical rivers and swamps', 'South America', 'Solitary, primarily aquatic snakes. Excellent swimmers, known for their constricting hunting method.', 'One of the world\'s largest snakes, olive green with black oval spots. Eyes and nostrils positioned on top of the head for swimming.'),
	(9, 'Raja', 'Bornean Orangutan (Pongo pygmaeus)', 2, 'Omnivore', 'The orangutan is an intelligent great ape.', 'Orangutans are known for their reddish-brown hair and remarkable ability to use tools.', _binary , 'Pongo pygmaeus', '35-45 years in the wild, up to 60 in captivity', 'Males: 50-90 kg; Females: 30-50 kg; Arm span: up to 2.4 m', '8-9 months, usually 1 infant', 'Tropical and subtropical moist broadleaf forests', 'Borneo', 'Semi-solitary, spend most of their time in trees. Females care for offspring for up to 8 years.', 'Distinctive reddish-brown fur, long arms, highly intelligent with tool use abilities. Pronounced sexual dimorphism with males having cheek flanges.');
INSERT INTO `animals` (`id`, `prenom`, `race`, `habitat_id`, `diet`, `description`, `characteristics`, `image`, `species`, `lifespan`, `size_weight`, `gestation`, `natural_habitat`, `native_region`, `lifestyle`, `distinctive_features`) VALUES
	(10, 'Tico', 'Scarlet Macaw (Ara macao)', 2, 'Herbivore', 'The scarlet macaw is a large, colorful parrot.', 'Macaws are known for their bright plumage and strong, curved beaks.', _binary , 'Ara macao', '40-50 years in the wild, up to 75 in captivity', 'Weight: 1-1.5 kg; Length: 80-90 cm (including tail)', '24-28 days incubation, 2-4 eggs', 'Tropical and subtropical forests', 'Central and South America', 'Monogamous pairs, often seen in large flocks. Highly intelligent and known for their ability to mimic human speech.', 'Vibrant red plumage with yellow and blue wing feathers. Large, hooked beak and long tail. Zygodactyl feet (two toes forward, two back).');
INSERT INTO `animals` (`id`, `prenom`, `race`, `habitat_id`, `diet`, `description`, `characteristics`, `image`, `species`, `lifespan`, `size_weight`, `gestation`, `natural_habitat`, `native_region`, `lifestyle`, `distinctive_features`) VALUES
	(11, 'Gator', 'American Alligator (Alligator mississippiensis)', 3, 'Carnivore', 'The American alligator is a large reptile found in wetlands.', 'Alligators are apex predators and have powerful jaws.', _binary , 'Alligator mississippiensis', '30-50 years in the wild, up to 70 in captivity', 'Males: up to 4.6 m, 450 kg; Females: up to 3 m, 170 kg', '65 days incubation, 20-50 eggs', 'Freshwater wetlands, rivers, lakes, swamps', 'Southeastern United States', 'Semi-aquatic predators, generally solitary but may congregate in groups. Females are protective of their young.', 'Armored body with tough scales, powerful tail, eyes and nostrils on top of head. Only two living alligator species worldwide.'),
	(12, 'Frodo', 'American Bullfrog (Lithobates catesbeianus)', 3, 'Carnivore', 'The American bullfrog is a large frog native to North America.', 'Bullfrogs are known for their loud calls and voracious appetites.', _binary , 'Lithobates catesbeianus', '7-9 years in the wild, up to 16 in captivity', 'Length: 9-15 cm, can reach up to 20 cm', 'External fertilization, 3-5 days to hatch, 2 years as tadpole', 'Permanent bodies of water in wetlands, ponds, lakes', 'Eastern North America, introduced elsewhere', 'Semi-aquatic, spend most time in or near water. Known for their loud, deep mating calls.', 'Largest frog in North America. Olive green to brown coloration, powerful legs for jumping, large tympanum (eardrums).'),
	(13, 'Nessie', 'Double-crested Cormorant (Phalacrocorax auritus)', 3, 'Carnivore', 'The double-crested cormorant is a water bird found in wetlands.', 'Cormorants are excellent divers and catch fish underwater.', _binary , 'Phalacrocorax auritus', '5-6 years average, up to 22 years', 'Weight: 1.2-2.5 kg; Wingspan: 114-123 cm', '25-28 days incubation, 3-4 eggs', 'Coastal areas, inland lakes, rivers', 'North America', 'Colonial nesters, often seen in large groups. Excellent divers, using their webbed feet to propel themselves underwater.', 'Dark-colored waterbird with hooked bill, long neck, and bright blue eyes. Lacks waterproof feathers, often seen spreading wings to dry.'),
	(14, 'Herbie', 'Great Blue Heron (Ardea herodias)', 3, 'Carnivore', 'The great blue heron is a large wading bird.', 'Great blue herons are known for their striking blue-gray plumage and long legs.', _binary , 'Ardea herodias', '15 years average, up to 24 years', 'Weight: 1.8-2.6 kg; Height: 91-137 cm; Wingspan: 167-201 cm', '25-30 days incubation, 3-5 eggs', 'Wetlands, shores of open water, fields', 'North and Central America, Caribbean', 'Often solitary feeders but may nest in colonies. Known for their patient hunting style, standing still or slowly stalking prey.', 'Tall wading bird with long legs, neck, and pointed bill. Blue-gray plumage, black stripe above the eye. S-shaped neck in flight.'),
	(15, 'Swampy', 'West Indian Manatee (Trichechus manatus)', 3, 'Herbivore', 'The West Indian manatee is a large, slow-moving marine mammal.', 'Manatees are gentle giants that graze on underwater vegetation.', _binary , 'Trichechus manatus', '40 years average, up to 60 years', 'Weight: 200-600 kg; Length: 2.5-4.5 m', '12-14 months, usually 1 calf', 'Shallow coastal areas, rivers, springs', 'Southeastern United States, Caribbean, northern South America', 'Gentle, slow-moving aquatic mammals. Often solitary but may gather in small groups. Can stay underwater for up to 20 minutes.', 'Large, gray-brown body with thick, wrinkled skin. Paddle-like flippers, round flat tail. Whiskered snouts with highly mobile, prehensile lips.'),
	(16, 'Nanook', 'Polar Bear (Ursus maritimus)', 4, 'Carnivore', 'The polar bear is a large bear species native to the Arctic.', 'Polar bears are excellent swimmers and primarily hunt seals.', _binary , 'Ursus maritimus', '20-30 years in the wild, up to 40 in captivity', 'Males: 350-700 kg; Females: 150-250 kg; Length: 2-3 m', '6-9 months, usually 1-3 cubs', 'Sea ice and coastal areas of the Arctic', 'Arctic Circle regions', 'Solitary animals, excellent swimmers. Females den during winter for cub birth and early care.', 'Largest land carnivore, white fur, black skin. Huge paws for swimming and walking on ice. Highly specialized for cold environments.'),
	(17, 'Blizzard', 'Arctic Fox (Vulpes lagopus)', 4, 'Omnivore', 'The Arctic fox is a small fox native to Arctic regions.', 'Arctic foxes have thick fur that provides insulation against the cold.', _binary , 'Vulpes lagopus', '3-6 years in the wild, up to 14 in captivity', 'Weight: 3-3.5 kg; Body length: 50-60 cm', '52 days, 5-8 pups on average', 'Arctic tundra, sea ice', 'Arctic regions of North America, Europe, Asia', 'Often monogamous, living in underground dens. Known for changing fur color seasonally - white in winter, brown in summer.', 'Compact body, thick fur, short legs and ears to minimize heat loss. Fur-covered foot pads for traction on ice and insulation.'),
	(18, 'Tundra', 'Caribou (Rangifer tarandus)', 4, 'Herbivore', 'The caribou, or reindeer, is a species of deer found in Arctic regions.', 'Caribou are known for their large antlers and migratory behavior.', _binary , 'Rangifer tarandus', '15 years in the wild, up to 20 in captivity', 'Males: 159-182 kg; Females: 80-120 kg; Shoulder height: 85-150 cm', '7.5 months, usually 1 calf', 'Arctic tundra, boreal forests', 'Northern North America, Europe, Asia', 'Highly migratory, traveling in large herds. Both males and females grow antlers annually.', 'Large deer with broad, concave hooves for walking on snow and digging for food. Thick fur with hollow hairs for insulation.'),
	(19, 'Snowy', 'Snowy Owl (Bubo scandiacus)', 4, 'Carnivore', 'The snowy owl is a large, white owl native to the Arctic.', 'Snowy owls are well adapted to cold environments and are skilled hunters.', _binary , 'Bubo scandiacus', '9-10 years in the wild, up to 28 in captivity', 'Weight: 1.6-3 kg; Wingspan: 125-150 cm', '31-33 days incubation, 3-11 eggs', 'Arctic tundra, open grasslands', 'Arctic regions of North America, Europe, Asia', 'Nomadic species, often moving south during winter. They are diurnal hunters, primarily active during daylight hours.', 'Large white owl with striking yellow eyes and black spots. Excellent camouflage in snowy environments. Silent flight and powerful talons.'),
	(20, 'Frost', 'Humboldt Penguin (Spheniscus humboldti)', 4, 'Carnivore', 'The Humboldt penguin is a species of penguin found in South America.', 'Humboldt penguins are excellent swimmers and feed on fish and squid.', _binary , 'Spheniscus humboldti', '15-20 years in the wild, up to 30 in captivity', 'Weight: 4-5 kg; Height: 65-70 cm', '39-42 days incubation, 2 eggs', 'Coastal areas, rocky shores', 'Coastal Peru and Chile', 'Social birds, often found in colonies. They are excellent swimmers, spending much of their time in the water hunting for fish.', 'Medium-sized penguin with a black head and a white border that runs from behind the eye, around the black ear-coverts, and chin, and joins at the throat. Black and white plumage provides camouflage while swimming.');
